-- Hosbah (MH-578 C10): the team's SSH key library — public keys only, never a private key. key_type
-- is ed25519 | rsa | ecdsa as parsed from public_key (internal/agentproto.ParseAuthorizedKey);
-- fingerprint is its SHA256 (OpenSSH's "SHA256:base64", no padding), used both to show the key and
-- as the marker Hosbah writes into a server's authorized_keys so an uninstall only ever removes the
-- one line (and its marker comment) it itself added — never Hosbah's own enrollment key or a line
-- with no marker. Rows go with their team.
ALTER TABLE ssh_keys ADD CONSTRAINT ssh_keys_name_check CHECK (length(name) BETWEEN 1 AND 80);
ALTER TABLE ssh_keys ADD CONSTRAINT ssh_keys_type_check CHECK (key_type IN ('ed25519', 'rsa', 'ecdsa'));
ALTER TABLE ssh_keys ADD CONSTRAINT ssh_keys_public_key_check CHECK (length(public_key) BETWEEN 1 AND 8192);
CREATE UNIQUE INDEX ssh_keys_team_name_key ON ssh_keys (team_id, name);
CREATE UNIQUE INDEX ssh_keys_team_fingerprint_key ON ssh_keys (team_id, fingerprint);
CREATE UNIQUE INDEX ssh_keys_id_team_key ON ssh_keys (id, team_id);
CREATE INDEX ssh_keys_team_idx ON ssh_keys (team_id);
